import{z as A,x as s,o as e,c as m,q as E,j as r,D as t,d as i,s as n,S as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"连续时间资产定价","description":"","frontmatter":{"title":"连续时间资产定价","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/apt-continuous-time.md","filePath":"econ/apt-continuous-time.md","lastUpdated":1791413859000}'),c={name:"econ/apt-continuous-time.md"};function h(p,a,l,_,d,u){const o=s("Mermaid");return e(),m("div",null,[a[2]||(a[2]=E('<h1 id="连续时间资产定价" tabindex="-1">连续时间资产定价 <a class="header-anchor" href="#连续时间资产定价" aria-label="Permalink to &quot;连续时间资产定价&quot;">​</a></h1><div class="epigraph"><p>连续时间把定价收成一条微分方程：漂移之差与载荷成正比，比例向量就是市场愿意为每一单位风险付的价格。</p><footer>—— 据 Merton, Econometrica 1973；Cochrane, Asset Pricing, 2005 年修订版 整理</footer></div><p><a href="/econ/pm-specification-map">上一课</a>把预测与机器学习计量收在目标声明、主结果保护与可复现三件套上，那门课程到此收束。本课是「资产定价理论深化」的第一课，从一条旧账说起：定价的需求一侧，<a href="/econ/brownian-ito">布朗运动与伊藤引理</a>给了微积分的 license，<a href="/econ/continuous-time-budget">连续时间预算约束</a>与<a href="/econ/merton-portfolio-theory">Merton 组合问题</a>写了需求方程，主干课末的<a href="/econ/multi-period-consumption-portfolio">多期消费组合</a>把多期版本收拢；但定价方程一侧还只在特例里出现过（<a href="/econ/bs-as-equilibrium">Black–Scholes 作为均衡结果</a>、<a href="/econ/continuous-time-capm">连续时间 CAPM</a>）。本课把两侧合成一个对象：核的随机微分方程，让 ICAPM、CCAPM、期权定价都成为它的特例。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离散时间的核 \\(m_{t+1}=\\beta u&#39;(c_{t+1})/u&#39;(c_t)\\) 回答「下一期一元值多少」，回答不了「此刻价格如何随状态微分」。机会集连续变化时，欧拉方程要写在每个无穷小区间上：溢价、无风险利率、对冲需求不再分期出现，而是同时挤进一条漂移方程。缺口是：<a href="/econ/stochastic-discount-factor">随机折现因子</a>在连续时间里的动力学长什么样，它对每只资产的开价如何读出。</p><h3 id="核的-sde-与定价方程" tabindex="-1">核的 SDE 与定价方程 <a class="header-anchor" href="#核的-sde-与定价方程" aria-label="Permalink to &quot;核的 SDE 与定价方程&quot;">​</a></h3><p>设核服从</p> \\[\\frac{dm_t}{m_t}=-r_t\\,dt-\\theta_t^{\\top}\\,\\mathrm{d}W_t , \\]<p>漂移取 \\(-r_t\\) 不是假设，是定义：核自身对应的「资产」必须给无风险利率，否则一元下期与一元本期之间没有账可平。任意资产若</p> \\[\\frac{dp_t^i}{p_t^i}=\\mu_t^i\\,dt+\\sigma_t^{i\\top}\\,\\mathrm{d}W_t , \\]<p>则<a href="/econ/continuous-time-budget">连续时间预算约束</a>下的欧拉条件立刻给出定价方程</p> \\[\\mu_t^i-r_t=\\sigma_t^{i\\top}\\theta_t . \\]<p>\\(\\theta_t\\) 是风险的市场价格向量：资产要求的风险补偿，等于它对 \\(\\mathrm{d}W\\) 的载荷点乘核的载荷。这与<a href="/econ/equivalent-martingale-measure">等价鞅测度</a>说的是一件事——\\(\\mathbb{P}\\to\\mathbb{Q}\\) 的测度变换密度正是 \\(m_t\\) 乘货币账户，倾斜的强度就是 \\(\\theta_t\\)（<a href="/econ/state-price-sdf-bridge">状态价格到 SDF</a> 的连续版）。</p><p><span class="marginnote">夏普按 \\(\\sqrt{dt}\\) 缩放：年化 0.5 的夏普比率，月度只有 \\(0.5/\\sqrt{12}\\approx 0.14\\)。所以「瞬时定价方程」不能拿月度收益直接去套——先把频率换算做对，是这条路线最常翻车的簿记。</span></p><p><span class="marginnote">\\(\\theta_t\\) 叫「风险的市场价格」，可以读成市场给每单位不可分散波动开出的补偿费率。数字实例：若 \\(r=2\\%\\)、某资产波动 \\(\\sigma=20\\%\\)、\\(\\theta=0.3\\)，则定价方程给出期望收益 \\(\\mu\\approx 2\\%+20\\%\\times 0.3=8\\%\\)——补偿只看波动的大小和费率，不看资产的名字。</span></p>',15)),(e(),r(B,null,{default:t(()=>[n(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E6%A0%B8%E7%9A%84%20SDE%EF%BC%9A%E6%BC%82%E7%A7%BB%20-r%EF%BC%8C%E8%BD%BD%E8%8D%B7%20-%CE%B8%22%5D%20--%3E%20PE%5B%22%E5%AE%9A%E4%BB%B7%E6%96%B9%E7%A8%8B%EF%BC%9A%CE%BC%20-%20r%20%3D%20%CF%83%C2%B7%CE%B8%22%5D%0A%20%20Q%5B%22%E6%B5%8B%E5%BA%A6%E5%8F%98%E6%8D%A2%20P%E2%86%92Q%EF%BC%9A%E5%80%BE%E6%96%9C%E5%8D%B3%E5%AE%9A%E4%BB%B7%22%5D%20--%3E%20K%0A%20%20PE%20--%3E%20IC%5B%22ICAPM%EF%BC%9A%E6%9C%BA%E4%BC%9A%E9%9B%86%E9%9A%8F%E7%8A%B6%E6%80%81%E5%8F%98%22%5D%0A%20%20PE%20--%3E%20CC%5B%22CCAPM%EF%BC%9A%CE%B8%20%E8%A2%AB%E6%B6%88%E8%B4%B9%E5%90%B8%E6%94%B6%22%5D%0A%20%20PE%20--%3E%20BSP%5B%22BS%EF%BC%9A%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%E4%B8%8E%E5%81%8F%E5%A5%BD%E6%97%A0%E5%85%B3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条特化各取一个方向。<a href="/econ/icapm-merton">ICAPM</a>：当 \\(r_t\\) 与 \\(\\theta_t\\) 随状态 \\(z_t\\) 变动，期望收益成为状态的函数，组合一侧的<a href="/econ/hedging-demand-origin">对冲需求</a>与定价一侧的时变 \\(\\theta_t\\) 是同一枚硬币——Merton 1973 把它们写成同一个均衡。CCAPM：取 \\(m_t=\\beta e^{-\\delta t}u&#39;(c_t)\\)，\\(\\theta_t\\) 被 \\(c_t\\) 的载荷吸收，溢价与消费 beta 成正比（<a href="/econ/ccapm">消费 CAPM</a>）。BS：相对价格（期权对标的）的定价方程里 \\(u\\) 被复制消掉，剩下的只是让该 \\(\\mathbb{Q}\\) 出现的核（<a href="/econ/bs-as-equilibrium">Black–Scholes 作为均衡结果</a>）。</p><p>跳跃要单独记账。若 \\(dp^i/p^i\\) 还含一项跳跃 \\(\\int z^i\\,\\tilde\\nu(\\mathrm{d}t,\\mathrm{d}z)\\)，定价方程变成 \\(\\mu_t^i-r_t=\\sigma_t^{i\\top}\\theta_t+\\phi_t^i\\)：跳跃有其自己的风险价格 \\(\\phi_t^i\\)，纯扩散的 \\(\\theta_t\\) 不给它开价。这一项正是后面尾部风险一课的入口，本课只立账。</p><p><span class="marginnote">直觉类比：\\(\\sigma^\\top\\theta\\) 是为「连续颠簸」付的保费，\\(\\phi\\) 是为「突发坑洞」另买的一份保单。只持有前一份保单（纯扩散定价方程）的组合，遇到 2008 式的跳空行情就拿不到赔偿——这正是尾部风险要单独立账、单独定价的原因。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>定价方程为什么这么便宜：在 \\(dt\\) 上，收益分布的高阶矩都是 \\(o(\\mathrm{d}t)\\)，均值与方差吞噬一切——所以连续时间天然把「均值方差即期望效用」的许可证（对照<a href="/econ/mean-variance-eu">均值方差与期望效用</a>）发给了局部区间，二阶以上的偏好信息全部堆进 \\(\\theta_t\\) 的动态。这既是威力也是代价：方程对「此刻」极有效率，对「核从哪里来」保持沉默，\\(r_t\\) 与 \\(\\theta_t\\) 的动态必须由均衡另给——<a href="/econ/cir-general-equilibrium">CIR 一般均衡利率</a>就是给 \\(r_t\\) 找均衡来源的一次尝试。</p><p>第一张图画的是定价方程的家族树；这一张拆的是「为什么方程这么便宜」——区间缩到无穷小时，各阶矩的量级赛跑如何让均值方差独占定价权。</p>',7)),(e(),r(B,null,{default:t(()=>[n(o,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20DT%5B%22%E6%8A%8A%E6%8C%81%E6%9C%89%E5%8C%BA%E9%97%B4%E7%BC%A9%E5%88%B0%20dt%22%5D%20--%3E%20MU%5B%22%E5%9D%87%E5%80%BC%E8%B4%A1%E7%8C%AE%20%E2%88%9D%20dt%22%5D%0A%20%20DT%20--%3E%20VAR%5B%22%E6%96%B9%E5%B7%AE%E8%B4%A1%E7%8C%AE%20%E2%88%9D%20dt%22%5D%0A%20%20DT%20--%3E%20HIGH%5B%22%E5%81%8F%E5%BA%A6%E3%80%81%E5%B3%B0%E5%BA%A6%E7%AD%89%E9%AB%98%E9%98%B6%E7%9F%A9%20%E2%88%9D%20o(dt)%22%5D%0A%20%20MU%20--%3E%20ABS%5B%22%E9%AB%98%E9%98%B6%E9%A1%B9%E7%9B%B8%E5%AF%B9%E5%9D%87%E5%80%BC%E6%96%B9%E5%B7%AE%E5%8F%AF%E5%BF%BD%E7%95%A5%22%5D%0A%20%20VAR%20--%3E%20ABS%0A%20%20ABS%20--%3E%20MV%5B%22%E5%B1%80%E9%83%A8%E5%8C%BA%E9%97%B4%E4%B8%8A%E5%9D%87%E5%80%BC%E6%96%B9%E5%B7%AE%E8%BF%91%E4%BC%BC%E5%A4%9F%E7%94%A8%22%5D%0A%20%20HIGH%20--%3E%20THETA%5B%22%E8%A2%AB%E4%B8%A2%E6%8E%89%E7%9A%84%E5%81%8F%E5%A5%BD%E4%BF%A1%E6%81%AF%E5%85%A8%E9%83%A8%E5%A0%86%E8%BF%9B%20%CE%B8%20%E7%9A%84%E5%8A%A8%E6%80%81%22%5D%0A%20%20MV%20--%3E%20THETA%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p><span class="marginnote">常见误区：以为连续时间模型是在假设「价格真的每一瞬间都在连续交易」。它其实是一套极限装置——把区间切到无穷小，数学最干净、方程最简洁；真实数据仍是离散采样，落地时必须做频率换算，别把装置当成对报价机的描述。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>瞬时方程不是实证区间：可观测的只有离散采样，\\(\\theta_t\\) 的点识别要靠本课程第二课的投影逻辑。跳跃与随机波动破坏精确复制，<a href="/econ/ftap">资产定价基本定理</a>在连续时间把无套利升级为 NFLVR，对偶精神仍在，但「一个 \\(\\mathbb{Q}\\) 定一切」的便利不再免费。也别把扩散当数据频率：<a href="/econ/brownian-ito">布朗运动与伊藤引理</a>的提醒在定价侧同样成立——连续时间是装置，不是对报价机的描述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>连续时间定价 = 核的 SDE 加定价方程 \\(\\mu-r=\\sigma^\\top\\theta\\)；漂移差对载荷线性，\\(\\theta\\) 是风险的市场价格。</li><li>ICAPM、CCAPM、BS 都是同一方程的特化：一个把机会集状态化，一个把核钉在消费上，一个让相对价格与偏好无关。</li><li>跳跃有自己的风险价格，纯扩散方程定价不了尾部。</li><li>瞬时方程效率极高但来源沉默；\\(r_t\\) 与 \\(\\theta_t\\) 的动态由均衡另给。</li><li>出处：Merton, <em>Econometrica</em> 1973；Lucas, <em>Econometrica</em> 1978；Breeden, <em>JFE</em> 1979；Cochrane, <em>Asset Pricing</em>, 2005 年修订版。</li></ul>',5))])}const D=A(c,[["render",h]]);export{f as __pageData,D as default};
